package com.sponsormatch.service;
import com.sponsormatch.dto.CollaborationDtos.*;import com.sponsormatch.entity.*;import com.sponsormatch.exception.ApiException;import com.sponsormatch.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class CollaborationService {private final ShortlistRepository shortlists;private final CollaborationRequestRepository requests;private final NotificationRepository notifications;private final UserRepository users;private final CampaignService campaigns;private final CreatorProfileRepository profiles;
 public ShortlistResponse add(Long brand,ShortlistRequest r){Campaign c=campaigns.owned(brand,r.campaignId());User creator=creator(r.creatorId());if(shortlists.existsByBrandIdAndCampaignIdAndCreatorId(brand,r.campaignId(),r.creatorId()))throw new ApiException(HttpStatus.CONFLICT,"Creator is already shortlisted for this campaign");Shortlist s=shortlists.save(Shortlist.builder().brand(c.getBrand()).campaign(c).creator(creator).build());return shortlist(s);}public List<ShortlistResponse> list(Long brand){return shortlists.findByBrandId(brand).stream().map(this::shortlist).toList();}public void remove(Long brand,Long id){Shortlist s=shortlists.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Shortlist not found"));if(!s.getBrand().getId().equals(brand))throw new ApiException(HttpStatus.FORBIDDEN,"You do not own this shortlist");shortlists.delete(s);}
 public CollaborationResponse send(Long brand,CollaborationRequestDto dto){Campaign c=campaigns.owned(brand,dto.campaignId());User creator=creator(dto.creatorId());CollaborationRequest r=requests.save(CollaborationRequest.builder().campaign(c).brand(c.getBrand()).creator(creator).message(dto.message().trim()).build());notice(creator,"New collaboration request for campaign '"+c.getTitle()+"'");return response(r);}public List<CollaborationResponse> sent(Long brand){return requests.findByBrandId(brand).stream().map(this::response).toList();}public List<CollaborationResponse> received(Long creator){return requests.findByCreatorId(creator).stream().map(this::response).toList();}public CollaborationResponse decide(Long creator,Long id,RequestStatus status){CollaborationRequest r=requests.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Collaboration request not found"));if(!r.getCreator().getId().equals(creator))throw new ApiException(HttpStatus.FORBIDDEN,"This request is not addressed to you");if(r.getStatus()!=RequestStatus.PENDING)throw new ApiException(HttpStatus.BAD_REQUEST,"Only pending requests can be updated");r.setStatus(status);requests.save(r);notice(r.getBrand(),r.getCreator().getName()+" "+status.name().toLowerCase()+" your collaboration request for '"+r.getCampaign().getTitle()+"'");return response(r);}public List<NotificationResponse> notifications(Long uid){return notifications.findByUserIdOrderByCreatedAtDesc(uid).stream().map(n->new NotificationResponse(n.getId(),n.getMessage(),n.isRead(),n.getCreatedAt())).toList();}public NotificationResponse read(Long uid,Long id){Notification n=notifications.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Notification not found"));if(!n.getUser().getId().equals(uid))throw new ApiException(HttpStatus.FORBIDDEN,"You do not own this notification");n.setRead(true);notifications.save(n);return new NotificationResponse(n.getId(),n.getMessage(),true,n.getCreatedAt());}private void notice(User u,String m){notifications.save(Notification.builder().user(u).message(m).build());}private User creator(Long id){return profiles.findById(id).map(CreatorProfile::getUser).or(()->users.findById(id).filter(user->user.getRole()==Role.CREATOR)).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Creator not found"));}private ShortlistResponse shortlist(Shortlist s){return new ShortlistResponse(s.getId(),s.getCampaign().getId(),s.getCreator().getId(),s.getCreator().getName(),s.getCreatedAt());}private CollaborationResponse response(CollaborationRequest r){return new CollaborationResponse(r.getId(),r.getCampaign().getId(),r.getCampaign().getTitle(),r.getBrand().getId(),r.getBrand().getName(),r.getCreator().getId(),r.getCreator().getName(),r.getMessage(),r.getStatus(),r.getCreatedAt());}}
